<script setup lang="ts">
import { ref, computed, watch } from 'vue'
import { api } from '../api'
import { usePage, perform, busy } from '../state'
import { decimal,label,requestKey,positiveDecimal,percent } from '../domain'
import type { Row } from '../domain'
import PageHeader from '../components/PageHeader.vue'
import DataTable from '../components/DataTable.vue'
import LoadState from '../components/LoadState.vue'
import TradeDialog from '../components/TradeDialog.vue'
const tab=ref('offering'),funds=ref<Row[]>([]),offerings=ref<Row[]>([]),dividends=ref<Row[]>([]),preferences=ref<Row[]>([]),income=ref<Row[]>([]),pairs=ref<Row[]>([]),conversions=ref<Row[]>([]),portfolio=ref<Row>({positions:[]}),trade=ref(false),selected=ref<Row|null>(null),form=ref<Row>({tradingAccountId:'',sourceClassId:'',targetClassId:'',shares:''}),conversionKey=ref(requestKey())
const history=ref<Row[]>([]),historyOpen=ref(false),historyApplication=ref<Row|null>(null)
async function showHistory(row:Row,kind='conversions'){await perform(async()=>{historyApplication.value=row;history.value=await api.get('/'+kind+'/'+row.id+'/confirmations');historyOpen.value=true})}
const conversionQuote=ref<Row|null>(null)
const {loading,error,load}=usePage(async()=>{[funds.value,offerings.value,dividends.value,preferences.value,income.value,pairs.value,conversions.value,portfolio.value]=await Promise.all([api.get('/funds'),api.get('/offering-orders'),api.get('/dividends'),api.get('/dividend-preferences'),api.get('/money-income'),api.get('/conversion-pairs'),api.get('/conversions'),api.get('/portfolio')])})
const targets=computed(()=>pairs.value.filter(p=>p.sourceClassId===Number(form.value.sourceClassId)&&p.enabled!==false).map(p=>funds.value.find(f=>f.id===p.targetClassId)).filter((f):f is Row=>!!f))
const sources=computed(()=>portfolio.value.positions.filter((p:Row)=>p.tradingAccountId===Number(form.value.tradingAccountId)&&pairs.value.some(pair=>pair.sourceClassId===p.fundClassId)))
const accountIds=computed(()=>[...new Set<number>(portfolio.value.positions.map((p:Row)=>p.tradingAccountId))])
watch(()=>form.value.tradingAccountId,()=>{form.value.sourceClassId='';form.value.targetClassId=''})
watch(()=>form.value.sourceClassId,()=>{form.value.targetClassId=''})
watch(form,()=>{conversionQuote.value=null;conversionKey.value=requestKey()},{deep:true})
function fundName(id:number){return funds.value.find(f=>f.id===id)?.name||'产品 '+id}
async function convert(){await perform(async()=>{if(!positiveDecimal(form.value.shares,4))throw new Error('转换份额需大于零，最多四位小数');return api.post('/conversions',{tradingAccountId:Number(form.value.tradingAccountId),sourceClassId:Number(form.value.sourceClassId),targetClassId:Number(form.value.targetClassId),shares:form.value.shares,requestKey:conversionKey.value})},async()=>{form.value.shares='';conversionKey.value=requestKey();await load()})}
async function preference(id:number,mode:string){await perform(()=>api.put('/dividend-preferences/'+id,{mode}),load)}
async function cancelConversion(row:Row){await perform(()=>api.post('/conversions/'+row.id+'/cancel'),load)}
async function previewConversion(){await perform(async()=>{if(!positiveDecimal(form.value.shares,4))throw new Error('转换份额需大于零，最多四位小数');if(!form.value.tradingAccountId||!form.value.sourceClassId||!form.value.targetClassId)throw new Error('请选择明确的来源账户、转出和转入产品');conversionQuote.value=await api.post('/conversions/quotes',{tradingAccountId:Number(form.value.tradingAccountId),sourceClassId:Number(form.value.sourceClassId),targetClassId:Number(form.value.targetClassId),shares:form.value.shares})})}
</script>
<template><PageHeader title="认购与收益" subtitle="完整了解募集、分红、货币收益与基金转换的进度。"><button class="button" @click="load">刷新</button></PageHeader><LoadState :loading="loading" :error="error" @retry="load"/><div class="tabs"><button v-for="t in [['offering','新基金认购'],['dividends','分红'],['money','货币收益'],['conversion','基金转换']]" :key="t[0]" :class="{active:tab===t[0]}" @click="tab=t[0]">{{ t[1] }}</button></div><template v-if="tab==='offering'"><section class="panel"><h2>募集中的产品</h2><div v-if="!funds.some(f=>f.state==='RAISING')" class="empty">暂无募集中的产品</div><div v-for="f in funds.filter(f=>f.state==='RAISING')" :key="f.id" class="message-item"><div class="toolbar"><h3>{{ f.name }}</h3><span class="muted">风险 R{{ f.riskLevel }} · {{ decimal(f.minPurchase) }} 元起</span><button class="button primary" @click="selected=f;trade=true">申请认购</button></div></div></section><section class="panel"><h2>认购与退款记录</h2><DataTable :rows="offerings" :columns="[{key:'orderNo',label:'认购编号'}, {key:'applicationNo',label:'申请编号'}, {key:'confirmationNo',label:'当前确认编号'}, {key:'fundName',label:'基金'}, {key:'tradingAccountId',label:'来源账户'}, {key:'amount',label:'认购金额（元）',kind:'money'}, {key:'interest',label:'模拟利息（元）',kind:'money'}, {key:'shares',label:'成立份额',kind:'shares'}, {key:'status',label:'状态',kind:'state'}, {key:'reason',label:'说明'}]"><template #cell-applicationNo="{row}">{{ row.applicationNo||'历史申请编号未采集' }}</template><template #cell-confirmationNo="{row}">{{ row.confirmationNo||'历史确认编号未采集' }}</template><template #actions="{row}"><button class="text-button" @click="showHistory(row,'orders')">确认历史</button></template></DataTable></section></template><template v-else-if="tab==='dividends'"><section class="panel"><h2>分红方式</h2><p class="notice">现金分红增加钱包现金，红利再投资形成新份额。分红不是额外凭空增加的收益；方式按客户与产品设置，权益与回款按来源账户分别登记。</p><div v-for="f in funds" :key="f.id" class="inline-form" style="padding:12px 0;border-bottom:1px solid var(--line)"><span style="flex:1">{{ f.name }}</span><span class="muted">{{ label(preferences.find(p=>p.fundClassId===f.id)?.mode || (f.type==='MONEY'?'REINVEST':'CASH')) }}</span><button class="text-button" :disabled="busy>0||f.type==='MONEY'" @click="preference(f.id,'CASH')">现金分红</button><button class="text-button" :disabled="busy>0" @click="preference(f.id,'REINVEST')">红利再投资</button></div></section><section class="panel"><h2>权益及发放记录</h2><DataTable :rows="dividends" :columns="[{key:'fundName',label:'基金'}, {key:'tradingAccountId',label:'权益账户'}, {key:'recordDate',label:'权益登记日'}, {key:'eligibleShares',label:'权益份额',kind:'shares'}, {key:'mode',label:'方式'}, {key:'amount',label:'红利金额（元）',kind:'money'}, {key:'reinvestShares',label:'再投资新增份额',kind:'shares'}, {key:'paymentDate',label:'支付日'}, {key:'status',label:'状态',kind:'state'}]"/></section></template><template v-else-if="tab==='money'"><section class="panel"><h2>每日收益与结转</h2><p class="notice">每日万份收益用于计算，七日年化只展示，不用于收入计算。持续持有时收益复投，全部赎回后的末期收益按来源账户现金结算；支持正负收益，包含周末自然日。</p><DataTable :rows="income" :columns="[{key:'fundName',label:'货币基金'}, {key:'tradingAccountId',label:'交易账户'}, {key:'date',label:'收益日期'}, {key:'incomePerTenThousand',label:'万份收益（元）',kind:'nav'}, {key:'annualYield',label:'七日年化',kind:'percent'}, {key:'eligibleShares',label:'计息份额',kind:'shares'}, {key:'amount',label:'收益金额（元）',kind:'money'}, {key:'addedShares',label:'新增份额',kind:'shares'}, {key:'cashAdjustment',label:'现金结算（元）',kind:'money'}, {key:'status',label:'结转状态',kind:'state'}]"/></section></template><template v-else><section class="panel"><h2>申请基金转换</h2><p class="notice">仅允许后台配置的同管理人产品组合。转入沿用来源交易账户与结算路径，不经过钱包充值提现。缺少任一侧适用净值时等待确认。</p><form class="form-grid" @submit.prevent="convert"><label><span>来源交易账户</span><select v-model="form.tradingAccountId" required><option disabled value="">请选择</option><option v-for="id in accountIds" :key="id" :value="id">交易账户 {{ id }}</option></select></label><label><span>转出基金</span><select v-model="form.sourceClassId" required><option disabled value="">请选择持有的支持转换产品</option><option v-for="p in sources" :key="p.fundClassId" :value="p.fundClassId">{{ p.fundName }} · 可用 {{ decimal(p.availableShares,4) }} 份</option></select></label><label><span>转入基金</span><select v-model="form.targetClassId" required><option disabled value="">请选择</option><option v-for="f in targets" :key="f.id" :value="f.id">{{ f.name }}</option></select></label><label><span>转换份额（份）</span><input v-model="form.shares" required inputmode="decimal" @input="conversionKey=requestKey()"/></label><p class="muted wide" v-if="form.sourceClassId&&form.targetClassId">转出基础费率 {{ percent(funds.find(f=>f.id===Number(form.sourceClassId))?.redemptionRate) }}；目标申购费率 {{ percent(funds.find(f=>f.id===Number(form.targetClassId))?.purchaseRate) }}。补差费率取目标与来源申购费率正差，实际费用按批次由后台确认。</p><div v-if="conversionQuote" class="wide"><div class="trade-summary"><div><span>转出参考净值 / 日期</span><b>{{ decimal(conversionQuote.sourceNav,6) }}</b><small>{{ conversionQuote.sourceNavDate }}</small></div><div><span>转入参考净值 / 日期</span><b>{{ decimal(conversionQuote.targetNav,6) }}</b><small>{{ conversionQuote.targetNavDate }}</small></div><div><span>转出费用（元）</span><b>{{ decimal(conversionQuote.redemptionFee) }}</b></div><div><span>补差费用（元）</span><b>{{ decimal(conversionQuote.supplementFee) }}</b></div><div><span>预估总费用（元）</span><b>{{ decimal(conversionQuote.totalFee) }}</b></div><div><span>预估转入份额（份）</span><b>{{ decimal(conversionQuote.targetShares,4) }}</b></div></div><p class="notice">该结果仅为参考预估，尚未成交或扣款。实际使用归属交易日双方净值确认，转换不扣钱包现金。</p></div><div class="wide toolbar"><button class="button" type="button" :disabled="busy>0 || !targets.length" @click="previewConversion">预估转换费用</button><button class="button primary" :disabled="busy>0 || !conversionQuote">提交转换申请</button></div></form></section><section class="panel"><h2>转换记录</h2><DataTable :rows="conversions" :columns="[{key:'id',label:'申请'}, {key:'applicationNo',label:'申请编号'}, {key:'confirmationNo',label:'当前确认编号'}, {key:'applicationDate',label:'归属交易日'}, {key:'sourceClassId',label:'转出产品'}, {key:'targetClassId',label:'转入产品'}, {key:'tradingAccountId',label:'来源账户'}, {key:'shares',label:'转出份额',kind:'shares'}, {key:'targetShares',label:'转入份额',kind:'shares'}, {key:'fee',label:'总费用（元）',kind:'money'}, {key:'status',label:'进度',kind:'state'}, {key:'reason',label:'说明'}]"><template #cell-sourceClassId="{row}">{{ fundName(row.sourceClassId) }}</template><template #cell-targetClassId="{row}">{{ fundName(row.targetClassId) }}</template><template #cell-applicationNo="{row}">{{ row.applicationNo||'历史申请编号未采集' }}</template><template #cell-confirmationNo="{row}">{{ row.confirmationNo||'历史确认编号未采集' }}</template><template #actions="{row}"><button class="text-button" @click="showHistory(row)">确认历史</button><button v-if="row.status==='SUBMITTED'" class="text-button danger" :disabled="busy>0" @click="cancelConversion(row)">撤销转换</button></template></DataTable></section></template><el-dialog v-model="historyOpen" title="确认历史" width="760px"><p>申请编号：{{ historyApplication?.applicationNo||'历史申请编号未采集' }} · 当前确认：{{ historyApplication?.confirmationNo||'历史确认编号未采集' }}</p><p v-if="!history.length" class="muted">尚无确认结果或历史确认编号未采集。</p><DataTable :rows="history" :columns="[{key:'confirmationNo',label:'确认编号'},{key:'roundId',label:'清算轮次'},{key:'status',label:'生效状态',kind:'state'},{key:'marketDate',label:'行情所属日'},{key:'effectiveDate',label:'资产业务有效日'},{key:'confirmationNumberDate',label:'确认编号日期'},{key:'processedAt',label:'真实处理时间',kind:'date'},{key:'shares',label:'转出/确认份额',kind:'shares'},{key:'targetShares',label:'转入份额',kind:'shares'},{key:'amount',label:'金额',kind:'money'}]"/></el-dialog><TradeDialog v-model="trade" :fund="selected" offering @submitted="load"/></template>
